            drawPath(AddedBadgePaths.p91, c3, style = Stroke(2.4f, cap = StrokeCap.Butt, join = StrokeJoin.Miter))
            drawPath(AddedBadgePaths.p92, c1)
            drawPath(AddedBadgePaths.p93, c3)
            drawPath(AddedBadgePaths.p94, c2)
        }
        "cat-graduation" -> if (blueprint) {
            drawPath(AddedBadgePaths.p95, c1)
            drawPath(AddedBadgePaths.p96, c2)
            drawPath(AddedBadgePaths.p97, c3, style = Stroke(2.5f, cap = StrokeCap.Butt, join = StrokeJoin.Miter))
            drawPath(AddedBadgePaths.p98, c1)
            drawPath(AddedBadgePaths.p99, c2)
            drawPath(AddedBadgePaths.p100, c3)
            drawPath(AddedBadgePaths.p101, dark)
            drawPath(AddedBadgePaths.p102, dark)
            drawPath(AddedBadgePaths.p103, c1)
        } else {
            drawPath(AddedBadgePaths.p95, c1)
            drawPath(AddedBadgePaths.p96, c2)
            drawPath(AddedBadgePaths.p97, c3, style = Stroke(2.5f, cap = StrokeCap.Butt, join = StrokeJoin.Miter))
            drawPath(AddedBadgePaths.p98, c1)
            drawPath(AddedBadgePaths.p99, c2)
            drawPath(AddedBadgePaths.p100, c3)
            drawPath(AddedBadgePaths.p101, dark)
            drawPath(AddedBadgePaths.p102, dark)
            drawPath(AddedBadgePaths.p103, c1)
        }
        "between-lines" -> if (blueprint) {
            drawPath(AddedBadgePaths.p104, c1)
            drawPath(AddedBadgePaths.p105, c3)
            drawPath(AddedBadgePaths.p106, c1)
            drawPath(AddedBadgePaths.p107, c3)
            drawPath(AddedBadgePaths.p108, dark)
            drawPath(AddedBadgePaths.p108, c2, style = Stroke(3.0f, cap = StrokeCap.Butt, join = StrokeJoin.Miter))
            drawPath(AddedBadgePaths.p109, c1, style = Stroke(2.0f, cap = StrokeCap.Butt, join = StrokeJoin.Miter))
            drawPath(AddedBadgePaths.p110, c1, style = Stroke(2.0f, cap = StrokeCap.Butt, join = StrokeJoin.Miter))
            drawPath(AddedBadgePaths.p111, c3)
        } else {
            drawPath(AddedBadgePaths.p104, c1)
            drawPath(AddedBadgePaths.p105, c3)
            drawPath(AddedBadgePaths.p106, c1)
            drawPath(AddedBadgePaths.p107, c3)
            drawPath(AddedBadgePaths.p108, dark)
            drawPath(AddedBadgePaths.p108, c2, style = Stroke(3.0f, cap = StrokeCap.Butt, join = StrokeJoin.Miter))
            drawPath(AddedBadgePaths.p109, c1, style = Stroke(2.0f, cap = StrokeCap.Butt, join = StrokeJoin.Miter))
            drawPath(AddedBadgePaths.p110, c1, style = Stroke(2.0f, cap = StrokeCap.Butt, join = StrokeJoin.Miter))
            drawPath(AddedBadgePaths.p111, c3)
        }
        "stars-aligned" -> if (blueprint) {
            drawPath(AddedBadgePaths.p112, c2)
            drawPath(AddedBadgePaths.p113, c1)
            drawPath(AddedBadgePaths.p114, dark)
            drawPath(AddedBadgePaths.p115, c3)
            drawPath(AddedBadgePaths.p116, c1)
            drawPath(AddedBadgePaths.p117, c3)
            drawPath(AddedBadgePaths.p118, c3)
            drawPath(AddedBadgePaths.p119, c1)
            drawPath(AddedBadgePaths.p120, c1)
            drawPath(AddedBadgePaths.p121, c3)
        } else {
            drawPath(AddedBadgePaths.p112, c2)
            drawPath(AddedBadgePaths.p113, c1)
            drawPath(AddedBadgePaths.p114, dark)
            drawPath(AddedBadgePaths.p115, c3)
            drawPath(AddedBadgePaths.p116, c1)
            drawPath(AddedBadgePaths.p117, c3)
            drawPath(AddedBadgePaths.p118, c3)
            drawPath(AddedBadgePaths.p119, c1)
            drawPath(AddedBadgePaths.p120, c1)
            drawPath(AddedBadgePaths.p121, c3)
        }
        else -> return false
    }
    return true
}
